arguments.command:
export DRIVE_SESSION_TAG="nothingness_linux_debug"; export DRIVE_TARGET=linux; export DRIVE_RUN_LOG="/tmp/flutter_run_${DRIVE_SESSION_TAG}.log"; export DRIVE_FLUTTER_FIFO="/tmp/flutter_input_${DRIVE_SESSION_TAG}"; export DRIVE_DESKTOP_HOME="/tmp/nothingness_${DRIVE_SESSION_TAG}"; 
D=.claude/skills/agent-emulator-debugging/scripts/drive.py;
$D pref screen_config_dot='{"type":"dot","showSongInfo":true,"textScale":1.0}':string;
$D screen dot;
$D play "/workspace/.tmp/The_Enormously_Long_Artist_Name_That_Should_Still_Fit_Above_The_Dot_When_Text_Is_Large - The_Ridiculously_Long_Song_Title_Metadata_That_Should_Remain_Visible_Without_Clipping_Or_Intersecting_The_Pulsing_Dot.wav";
sleep 0.4;
$D inspect | grep -A8 "playback" -n; 
$D probe hero-artist; 
$D shoot dot_textScale_normal

